569:   {
570:     const V invCs2  = descriptors::invCs2<V, DESCRIPTOR>();
571:     const V invCs4  = invCs2 * invCs2;
572: 
573:     for (int iPop = 0; iPop < DESCRIPTOR::q; ++iPop) {
574:       V c_u{};
575:       for (int iD = 0; iD < DESCRIPTOR::d; ++iD) {
576:         c_u += descriptors::c<DESCRIPTOR>(iPop, iD) * u[iD];
577:       }
578:       c_u *= invCs4;
579: 
580:       V forceTerm{};
581:       for (int iD = 0; iD < DESCRIPTOR::d; ++iD) {
582:         forceTerm += ((descriptors::c<DESCRIPTOR>(iPop, iD) - u[iD]) * invCs2 + c_u * descriptors::c<DESCRIPTOR>(iPop, iD)) * force[iD];
583:       }
584:       forceTerm *= (rho * (V{1} - omega * V{0.5}) * descriptors::t<V, DESCRIPTOR>(iPop));
585: 
586:       cell[iPop] += forceTerm;
587:     }

